import sys, json, random
sys.path.insert(0, 'tmp'); sys.path.insert(0, 'submission')
import ref, main as M
# order-invariance test on a cactus with many links, using random valid orders
rnd = random.Random(4)
def build(ncyc):
    asn = 5000; shared = None; rib = []; cycles=[]
    for c in range(ncyc):
        n = rnd.randint(4,6); cyc=[]
        if shared is not None: cyc.append(shared)
        while len(cyc) < n:
            asn += rnd.randint(2,9); cyc.append(asn)
        shared = cyc[len(cyc)//2]; cycles.append(cyc)
        for i in range(n):
            L = rnd.randint(2, min(5, n-1))
            p = [cyc[(i+j)%n] for j in range(L+1)]
            if rnd.random()<0.5: p = p[::-1]
            rib.append({'path':p,'count':rnd.randint(1,7)})
    agg={}
    for r in rib:
        t=tuple(r['path']); agg[t]=agg.get(t,0)+r['count']
    final, rounds = ref.ref_peel(agg)
    core=set()
    for p in final:
        for i in range(len(p)-1): core.add(ref.canon(p[i],p[i+1]))
    occs = ref.ref_occurrences(final)
    adj = ref.scope_graph(occs, core)
    return agg, final, core, adj

agg, final, core, adj = build(10)
# generate several valid elimination orders (random greedy with width<=4)
def rand_order(adj, rnd):
    cur = {k:set(v) for k,v in adj.items()}
    order=[]
    while cur:
        cands = [k for k in cur if len(cur[k]) <= 4]
        if not cands: return None
        k = rnd.choice(cands)
        nbrs = cur.pop(k)
        for a in nbrs: cur[a].discard(k)
        for a in nbrs:
            for b in nbrs:
                if a!=b: cur[a].add(b)
        order.append(k)
    return order

results = set()
for trial in range(12):
    order = rand_order(adj, rnd)
    if order is None: 
        print("no valid order for trial", trial); continue
    vi = {l:i for i,l in enumerate(order)}
    occs_m = M.collect_occurrences(final)
    factors = [M.build_factor(l, occs_m.get(l,[]), vi) for l in order]
    Z, marg = M.infer(factors, len(order))
    res = (Z, tuple(tuple(marg[vi[l]]) for l in sorted(core)))
    results.add(res)
print("distinct (Z, marginals) across orders:", len(results))
print("core links:", len(core), "Z:", list(results)[0][0] if results else None)
EOF
